package com.loopers.interfaces.api.payment;
import com.loopers.application.payment.PaymentFacade;import com.loopers.domain.payment.*;import com.loopers.infrastructure.payment.PaymentJpaRepository;import com.loopers.utils.DatabaseCleanUp;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.context.annotation.*;import org.springframework.test.context.ContextConfiguration;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest @Import(PaymentIntegrationTest.Config.class) class PaymentIntegrationTest{@Autowired PaymentFacade facade;@Autowired ControlledPgGateway pg;@Autowired DatabaseCleanUp cleanup;@AfterEach void clean(){cleanup.truncateAllTables();pg.reset();}@Test void responseLossReconcilesWithoutSecondDispatch(){pg.drop=true;PaymentIntent p=facade.dispatch(42,"attempt-01",1000);assertThat(p.getStatus()).isEqualTo(PaymentIntent.Status.UNKNOWN);facade.dispatch(42,"attempt-01",1000);assertThat(pg.dispatches).isEqualTo(1);pg.drop=false;PaymentIntent settled=facade.reconcile(p.getId());assertThat(settled.getStatus()).isEqualTo(PaymentIntent.Status.CONFIRMED);assertThat(pg.effects).isEqualTo(1);}@Test void zeroAndMultipleLookupsDoNotGuessAndLateConflictDoesNotOverwrite(){pg.drop=true;PaymentIntent p=facade.dispatch(43,"attempt-02",1000);pg.found=0;assertThat(facade.reconcile(p.getId()).getStatus()).isEqualTo(PaymentIntent.Status.UNKNOWN);pg.found=2;org.junit.jupiter.api.Assertions.assertThrows(RuntimeException.class,()->facade.reconcile(p.getId()));facade.callback(p.getProviderOrderId(),"tx-1","CONFIRMED");assertThat(facade.callback(p.getProviderOrderId(),"tx-1","FAILED").getStatus()).isEqualTo(PaymentIntent.Status.CONFIRMED);}@TestConfiguration static class Config{@Bean @Primary ControlledPgGateway gateway(){return new ControlledPgGateway();}}static class ControlledPgGateway implements PaymentGateway{int dispatches,effects,found=1;boolean drop;public Result create(String u,Request r){assertThat(u).isEqualTo("135135");dispatches++;if(dispatches>1)throw new AssertionError("second dispatch");effects++;if(drop)throw new RuntimeException("response dropped");return new Result("tx-1",r.orderId(),"CONFIRMED");}public List<Result> findByOrderId(String u,String o){List<Result> x=new ArrayList<>();for(int i=0;i<found;i++)x.add(new Result("tx-"+i,o,"CONFIRMED"));return x;}public Result findByTransactionKey(String u,String k){return new Result(k,"LP-ORD-0000000042","CONFIRMED");}void reset(){dispatches=effects=0;found=1;drop=false;}}}
